export default {
  id: 'event-counter',
  name: 'Event Counter',
  version: '1.0.0',
  onLoad(ctx: PluginContext) {
    let observed: number | null = null;

    ctx.register({
      kind: 'listener',
      event: 'counter.value',
      listener: (event: unknown) => {
