        description: 'Emit counter.value with data.value 27 and return the value observed by this plugin instance listener.',
        permissions: [],
        sideEffect: 'none',
        parameters: { type: 'object', properties: {}, required: [] },
        outputSchema: {
          type: 'object',
          properties: {
            event: { type: 'number' },
            observed: {},
            value: { type: 'number' },
          },
          required: ['event', 'observed', 'value'],
        },
        async handler(_args: unknown, _tctx: unknown) {
